def proverb(*pieces, qualifier=None):
    lines = []
    for current, next_ in zip(pieces, pieces[1:]):
        lines.append(f"For want of a {current} the {next_} was lost.")
    if pieces:
        first = pieces[0]
        if qualifier:
            first = f"{qualifier} {first}"
        lines.append(f"And all for the want of a {first}.")
    return lines
